-- Cơ hội (một vị trí chủ tàu cần người), hồ sơ yêu cầu, ứng viên, ghi nhận gửi chủ tàu; chuyến mới mỗi dòng một thuyền viên.
-- Bảng voyage / voyage_position cũ giữ nguyên cho hợp đồng và yêu cầu thanh toán đọc (giai đoạn 1 không nối hợp đồng).

COMMENT ON TABLE "voyage" IS 'Chuyến cũ (gom vị trí). Chỉ còn hợp đồng đọc; chuyến mới ở seafarer_voyage.';
COMMENT ON TABLE "voyage_position" IS 'Vị trí của chuyến cũ. Chỉ còn hợp đồng đọc; vị trí mới là opportunity.';

CREATE TABLE "opportunity" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "code" varchar(20) NOT NULL UNIQUE,
  "ship_owner_id" INTEGER NOT NULL REFERENCES "ship_owner" ("id"),
  "vessel_id" INTEGER REFERENCES "vessel" ("id"),
  "rank_id" INTEGER NOT NULL REFERENCES "rank" ("id"),
  "budget_monthly_usd" decimal(12,2) NOT NULL CHECK ("budget_monthly_usd" >= 0),
  "budget_total_usd" decimal(12,2) NOT NULL CHECK ("budget_total_usd" >= 0),
  "planned_join_date" DATE NOT NULL,
  "planned_join_port_id" INTEGER REFERENCES "port" ("id"),
  "planned_leave_date" DATE NOT NULL,
  "planned_leave_port_id" INTEGER REFERENCES "port" ("id"),
  "deadline" DATE NOT NULL,
  "owner_user_id" INTEGER NOT NULL REFERENCES "user" ("id"),
  "status" varchar(20) NOT NULL DEFAULT 'OPEN',
  "close_reason" TEXT,
  "notes" TEXT,
  "legacy_voyage_id" INTEGER REFERENCES "voyage" ("id"),
  "legacy_position_id" INTEGER UNIQUE REFERENCES "voyage_position" ("id"),
  "created_by" INTEGER,
  "updated_by" INTEGER,
  "created_at" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_at" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "deleted_at" TIMESTAMP WITHOUT TIME ZONE,
  CONSTRAINT "opportunity_status_check" CHECK ("status" IN ('OPEN', 'WON', 'LOST', 'CANCELLED')),
  CONSTRAINT "opportunity_dates_check" CHECK ("planned_leave_date" >= "planned_join_date"),
  CONSTRAINT "opportunity_lost_check" CHECK ("status" <> 'LOST' OR "close_reason" IS NOT NULL)
);
CREATE TRIGGER "opportunity_updated_at" BEFORE UPDATE ON "opportunity" FOR EACH ROW EXECUTE FUNCTION touch_updated_at();
CREATE INDEX "opportunity_vessel_idx" ON "opportunity" ("vessel_id") WHERE "deleted_at" IS NULL;
CREATE INDEX "opportunity_owner_idx" ON "opportunity" ("ship_owner_id") WHERE "deleted_at" IS NULL;
CREATE INDEX "opportunity_status_idx" ON "opportunity" ("status", "deadline") WHERE "deleted_at" IS NULL;

-- Một dòng một yêu cầu. Cột dùng theo kind: CERTIFICATE → certificate_type_id; EXPERIENCE → rank_id + min_months
-- hoặc vessel_type_id + min_trips; TEMPLATE → template_key (khoá trong PACK_TEMPLATES).
CREATE TABLE "opportunity_requirement" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "opportunity_id" INTEGER NOT NULL REFERENCES "opportunity" ("id") ON DELETE CASCADE,
  "kind" varchar(12) NOT NULL,
  "certificate_type_id" INTEGER REFERENCES "certificate_type" ("id"),
  "rank_id" INTEGER REFERENCES "rank" ("id"),
  "vessel_type_id" INTEGER REFERENCES "vessel_type" ("id"),
  "min_months" SMALLINT CHECK ("min_months" > 0),
  "min_trips" SMALLINT CHECK ("min_trips" > 0),
  "template_key" varchar(20),
  "level" varchar(10) NOT NULL DEFAULT 'REQUIRED',
  "valid_until" varchar(12) NOT NULL DEFAULT 'LEAVE',
  "plus_months" SMALLINT CHECK ("plus_months" > 0),
  "sort_order" SMALLINT NOT NULL DEFAULT 0,
  CONSTRAINT "opportunity_requirement_kind_check" CHECK ("kind" IN ('CERTIFICATE', 'EXPERIENCE', 'TEMPLATE')),
  CONSTRAINT "opportunity_requirement_level_check" CHECK ("level" IN ('REQUIRED', 'PREFERRED')),
  CONSTRAINT "opportunity_requirement_valid_check" CHECK ("valid_until" IN ('JOIN', 'LEAVE', 'LEAVE_PLUS', 'ANY')),
  CONSTRAINT "opportunity_requirement_plus_check" CHECK (("valid_until" = 'LEAVE_PLUS') = ("plus_months" IS NOT NULL)),
  CONSTRAINT "opportunity_requirement_shape_check" CHECK (
    ("kind" = 'CERTIFICATE' AND "certificate_type_id" IS NOT NULL AND "rank_id" IS NULL AND "vessel_type_id" IS NULL AND "template_key" IS NULL)
    OR ("kind" = 'EXPERIENCE' AND "certificate_type_id" IS NULL AND "template_key" IS NULL
        AND (("rank_id" IS NOT NULL AND "min_months" IS NOT NULL AND "vessel_type_id" IS NULL)
          OR ("vessel_type_id" IS NOT NULL AND "min_trips" IS NOT NULL AND "rank_id" IS NULL)))
    OR ("kind" = 'TEMPLATE' AND "template_key" IS NOT NULL AND "certificate_type_id" IS NULL AND "rank_id" IS NULL AND "vessel_type_id" IS NULL)
  )
);
CREATE INDEX "opportunity_requirement_opp_idx" ON "opportunity_requirement" ("opportunity_id");

-- Mẫu hồ sơ yêu cầu theo chức danh (preset_rank_id). Cột yêu cầu giống opportunity_requirement.
CREATE TABLE "rank_requirement_preset" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "preset_rank_id" INTEGER NOT NULL REFERENCES "rank" ("id") ON DELETE CASCADE,
  "kind" varchar(12) NOT NULL,
  "certificate_type_id" INTEGER REFERENCES "certificate_type" ("id"),
  "rank_id" INTEGER REFERENCES "rank" ("id"),
  "vessel_type_id" INTEGER REFERENCES "vessel_type" ("id"),
  "min_months" SMALLINT CHECK ("min_months" > 0),
  "min_trips" SMALLINT CHECK ("min_trips" > 0),
  "template_key" varchar(20),
  "level" varchar(10) NOT NULL DEFAULT 'REQUIRED',
  "valid_until" varchar(12) NOT NULL DEFAULT 'LEAVE',
  "plus_months" SMALLINT CHECK ("plus_months" > 0),
  "sort_order" SMALLINT NOT NULL DEFAULT 0,
  CONSTRAINT "rank_requirement_preset_kind_check" CHECK ("kind" IN ('CERTIFICATE', 'EXPERIENCE', 'TEMPLATE')),
  CONSTRAINT "rank_requirement_preset_level_check" CHECK ("level" IN ('REQUIRED', 'PREFERRED')),
  CONSTRAINT "rank_requirement_preset_valid_check" CHECK ("valid_until" IN ('JOIN', 'LEAVE', 'LEAVE_PLUS', 'ANY')),
  CONSTRAINT "rank_requirement_preset_plus_check" CHECK (("valid_until" = 'LEAVE_PLUS') = ("plus_months" IS NOT NULL)),
  CONSTRAINT "rank_requirement_preset_shape_check" CHECK (
    ("kind" = 'CERTIFICATE' AND "certificate_type_id" IS NOT NULL AND "rank_id" IS NULL AND "vessel_type_id" IS NULL AND "template_key" IS NULL)
    OR ("kind" = 'EXPERIENCE' AND "certificate_type_id" IS NULL AND "template_key" IS NULL
        AND (("rank_id" IS NOT NULL AND "min_months" IS NOT NULL AND "vessel_type_id" IS NULL)
          OR ("vessel_type_id" IS NOT NULL AND "min_trips" IS NOT NULL AND "rank_id" IS NULL)))
    OR ("kind" = 'TEMPLATE' AND "template_key" IS NOT NULL AND "certificate_type_id" IS NULL AND "rank_id" IS NULL AND "vessel_type_id" IS NULL)
  )
);
CREATE INDEX "rank_requirement_preset_rank_idx" ON "rank_requirement_preset" ("preset_rank_id");

CREATE TABLE "opportunity_candidate" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "opportunity_id" INTEGER NOT NULL REFERENCES "opportunity" ("id"),
  "seafarer_id" INTEGER NOT NULL REFERENCES "seafarer" ("id"),
  "status" varchar(15) NOT NULL DEFAULT 'PICKED',
  "source" varchar(10) NOT NULL DEFAULT 'SEARCH',
  "owner_selected_at" TIMESTAMP WITHOUT TIME ZONE,
  "owner_selected_by" INTEGER REFERENCES "user" ("id"),
  "export_pack_id" INTEGER REFERENCES "export_pack" ("id"),
  "last_sent_at" TIMESTAMP WITHOUT TIME ZONE,
  "added_by" INTEGER,
  "created_at" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_at" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  UNIQUE ("opportunity_id", "seafarer_id"),
  CONSTRAINT "opportunity_candidate_status_check" CHECK ("status" IN ('PICKED', 'PLACED', 'NOT_SELECTED', 'REMOVED')),
  CONSTRAINT "opportunity_candidate_source_check" CHECK ("source" IN ('SUGGEST', 'SEARCH'))
);
CREATE TRIGGER "opportunity_candidate_updated_at" BEFORE UPDATE ON "opportunity_candidate" FOR EACH ROW EXECUTE FUNCTION touch_updated_at();
-- Một người mang nhãn Chủ tàu đã chọn mỗi cơ hội; một người được chốt mỗi cơ hội.
CREATE UNIQUE INDEX "opportunity_candidate_selected_uniq" ON "opportunity_candidate" ("opportunity_id") WHERE "owner_selected_at" IS NOT NULL;
CREATE UNIQUE INDEX "opportunity_candidate_placed_uniq" ON "opportunity_candidate" ("opportunity_id") WHERE "status" = 'PLACED';
CREATE INDEX "opportunity_candidate_seafarer_idx" ON "opportunity_candidate" ("seafarer_id");

-- Ghi nhận đã gửi chủ tàu (email gửi từ app mail của máy, server không gửi).
CREATE TABLE "opportunity_send" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "opportunity_id" INTEGER NOT NULL REFERENCES "opportunity" ("id"),
  "ship_owner_contact_id" INTEGER REFERENCES "ship_owner_contact" ("id") ON DELETE SET NULL,
  "to_email" varchar(150) NOT NULL,
  "subject" varchar(300) NOT NULL,
  "candidate_ids" INTEGER[] NOT NULL,
  "export_pack_ids" INTEGER[] NOT NULL,
  "sent_by" INTEGER NOT NULL REFERENCES "user" ("id"),
  "sent_at" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE INDEX "opportunity_send_opp_idx" ON "opportunity_send" ("opportunity_id");

CREATE TABLE "seafarer_voyage" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "code" varchar(20) NOT NULL UNIQUE,
  "seafarer_id" INTEGER NOT NULL REFERENCES "seafarer" ("id"),
  "rank_id" INTEGER NOT NULL REFERENCES "rank" ("id"),
  "vessel_id" INTEGER NOT NULL REFERENCES "vessel" ("id"),
  "ship_owner_id" INTEGER NOT NULL REFERENCES "ship_owner" ("id"),
  "opportunity_id" INTEGER REFERENCES "opportunity" ("id"),
  "source" varchar(12) NOT NULL,
  "manual_reason" varchar(12),
  "transferred_from_id" INTEGER REFERENCES "seafarer_voyage" ("id"),
  "budget_monthly_usd" decimal(12,2) CHECK ("budget_monthly_usd" >= 0),
  "join_date" DATE NOT NULL,
  "join_port_id" INTEGER NOT NULL REFERENCES "port" ("id"),
  "planned_leave_date" DATE NOT NULL,
  "planned_leave_port_id" INTEGER REFERENCES "port" ("id"),
  "original_leave_date" DATE,
  "leave_date" DATE,
  "leave_port_id" INTEGER REFERENCES "port" ("id"),
  "leave_note" TEXT,
  "status" varchar(10) NOT NULL DEFAULT 'ONBOARD',
  "notes" TEXT,
  "legacy_voyage_id" INTEGER REFERENCES "voyage" ("id"),
  "legacy_contract_id" INTEGER UNIQUE REFERENCES "seafarer_contract" ("id"),
  "created_by" INTEGER,
  "updated_by" INTEGER,
  "created_at" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_at" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "deleted_at" TIMESTAMP WITHOUT TIME ZONE,
  CONSTRAINT "seafarer_voyage_status_check" CHECK ("status" IN ('ONBOARD', 'LEFT')),
  CONSTRAINT "seafarer_voyage_source_check" CHECK ("source" IN ('OPPORTUNITY', 'MANUAL') AND (("source" = 'OPPORTUNITY') = ("opportunity_id" IS NOT NULL))),
  CONSTRAINT "seafarer_voyage_manual_check" CHECK (("source" = 'MANUAL') = ("manual_reason" IS NOT NULL)
    AND ("manual_reason" IS NULL OR "manual_reason" IN ('TRANSFER', 'OWNER_HIRED', 'LEGACY', 'OTHER'))),
  CONSTRAINT "seafarer_voyage_left_check" CHECK (("status" = 'LEFT') = ("leave_date" IS NOT NULL AND "leave_port_id" IS NOT NULL)),
  CONSTRAINT "seafarer_voyage_dates_check" CHECK ("planned_leave_date" >= "join_date" AND ("leave_date" IS NULL OR "leave_date" >= "join_date"))
);
CREATE TRIGGER "seafarer_voyage_updated_at" BEFORE UPDATE ON "seafarer_voyage" FOR EACH ROW EXECUTE FUNCTION touch_updated_at();
CREATE UNIQUE INDEX "seafarer_voyage_opportunity_uniq" ON "seafarer_voyage" ("opportunity_id") WHERE "opportunity_id" IS NOT NULL AND "deleted_at" IS NULL;
-- Mỗi thuyền viên tối đa một chuyến đang trên tàu.
CREATE UNIQUE INDEX "seafarer_voyage_onboard_uniq" ON "seafarer_voyage" ("seafarer_id") WHERE "status" = 'ONBOARD' AND "deleted_at" IS NULL;
CREATE INDEX "seafarer_voyage_vessel_time_idx" ON "seafarer_voyage" ("vessel_id", "join_date", "leave_date") WHERE "deleted_at" IS NULL;
CREATE INDEX "seafarer_voyage_seafarer_idx" ON "seafarer_voyage" ("seafarer_id") WHERE "deleted_at" IS NULL;

CREATE TABLE "seafarer_voyage_log" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "voyage_id" INTEGER NOT NULL REFERENCES "seafarer_voyage" ("id") ON DELETE CASCADE,
  "action" varchar(20) NOT NULL,
  "actor_id" INTEGER REFERENCES "user" ("id"),
  "payload" JSONB,
  "created_at" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  CONSTRAINT "seafarer_voyage_log_action_check" CHECK ("action" IN ('PLACE', 'CREATE', 'LEAVE', 'LEAVE_PLAN', 'EDIT_DATES', 'TRANSFER_OUT', 'DELETE', 'MIGRATE'))
);
CREATE INDEX "seafarer_voyage_log_voyage_idx" ON "seafarer_voyage_log" ("voyage_id");

ALTER TABLE "export_pack" ADD COLUMN "opportunity_id" INTEGER REFERENCES "opportunity" ("id");
CREATE INDEX "export_pack_opportunity_idx" ON "export_pack" ("opportunity_id") WHERE "opportunity_id" IS NOT NULL;

-- ---------- Chuyển dữ liệu chuyến cũ (chỉ đọc bảng cũ) ----------

DO $$
DECLARE bad TEXT;
BEGIN
  SELECT string_agg(v.code, ', ') INTO bad FROM "voyage" v
  WHERE v.deleted_at IS NULL AND v.status <> 'PLANNING' AND v.embark_port_id IS NULL;
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'Chuyến cũ đã bắt đầu nhưng thiếu nơi xuống tàu: %', bad; END IF;
  SELECT string_agg(v.code, ', ') INTO bad FROM "voyage" v
  WHERE v.deleted_at IS NULL AND v.status = 'ENDED' AND v.disembark_port_id IS NULL;
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'Chuyến cũ đã kết thúc nhưng thiếu nơi rời tàu: %', bad; END IF;
  SELECT string_agg(s.full_name, ', ') INTO bad FROM (
    SELECT c.seafarer_id FROM "seafarer_contract" c
    JOIN "voyage_position" p ON p.id = c.voyage_position_id JOIN "voyage" v ON v.id = p.voyage_id
    WHERE c.deleted_at IS NULL AND p.deleted_at IS NULL AND v.deleted_at IS NULL AND v.status = 'ONBOARD'
    GROUP BY c.seafarer_id HAVING COUNT(*) > 1
  ) x JOIN "seafarer" s ON s.id = x.seafarer_id;
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'Thuyền viên có hai hợp đồng ở chuyến cũ đang trên tàu: %', bad; END IF;
END $$;

-- Hợp đồng còn sống của từng vị trí cũ (mỗi vị trí tối đa một, theo index cũ).
CREATE TEMP TABLE "legacy_slot" ON COMMIT DROP AS
SELECT p.id AS position_id, p.rank_id, p.budget_monthly_usd, p.budget_total_usd, p.sort_order,
       v.id AS voyage_id, v.code AS voyage_code, v.vessel_id, v.ship_owner_id, v.status AS voyage_status,
       v.embark_port_id, v.disembark_port_id, v.planned_embark_date, v.planned_disembark_date,
       v.actual_embark_date, v.actual_disembark_date, v.notes, v.created_by AS voyage_created_by, v.created_at AS voyage_created_at,
       c.id AS contract_id, c.seafarer_id, c.start_date, c.end_date, c.created_by AS contract_created_by,
       -- Người đã lên tàu thật: hợp đồng Hiệu lực / Hết hạn ở chuyến đã bắt đầu (cùng điều kiện cũ để đặt ON_VESSEL).
       (c.status IN ('ACTIVE', 'ENDED') AND v.status IN ('ONBOARD', 'ENDED')) AS boarded
FROM "voyage_position" p
JOIN "voyage" v ON v.id = p.voyage_id AND v.deleted_at IS NULL
LEFT JOIN "seafarer_contract" c ON c.voyage_position_id = p.id AND c.deleted_at IS NULL
WHERE p.deleted_at IS NULL;

INSERT INTO "opportunity" (
  "code", "ship_owner_id", "vessel_id", "rank_id", "budget_monthly_usd", "budget_total_usd",
  "planned_join_date", "planned_join_port_id", "planned_leave_date", "planned_leave_port_id", "deadline",
  "owner_user_id", "status", "close_reason", "notes", "legacy_voyage_id", "legacy_position_id", "created_by", "created_at"
)
SELECT
  'CH-' || EXTRACT(YEAR FROM ls.voyage_created_at)::int || '-'
    || lpad((ROW_NUMBER() OVER (PARTITION BY EXTRACT(YEAR FROM ls.voyage_created_at) ORDER BY ls.voyage_id, ls.sort_order, ls.position_id))::text, 3, '0'),
  ls.ship_owner_id, ls.vessel_id, ls.rank_id, ls.budget_monthly_usd, ls.budget_total_usd,
  ls.planned_embark_date, ls.embark_port_id, ls.planned_disembark_date, ls.disembark_port_id, ls.planned_embark_date,
  COALESCE(
    (SELECT u.id FROM "user" u WHERE u.id = ls.voyage_created_by),
    (SELECT MIN(u.id) FROM "user" u JOIN "role" r ON r.id = u.role_id WHERE r.code = 'admin'),
    (SELECT MIN(u.id) FROM "user" u)
  ),
  CASE
    WHEN ls.boarded THEN 'WON'
    WHEN ls.contract_id IS NULL AND ls.voyage_status = 'ENDED' THEN 'CANCELLED'
    ELSE 'OPEN'
  END,
  CASE WHEN ls.contract_id IS NULL AND ls.voyage_status = 'ENDED' THEN 'Chuyển từ chuyến cũ, không có người' END,
  'Chuyển từ ' || ls.voyage_code || COALESCE(' · ' || ls.notes, ''),
  ls.voyage_id, ls.position_id, ls.voyage_created_by, ls.voyage_created_at
FROM "legacy_slot" ls;

INSERT INTO "seafarer_voyage" (
  "code", "seafarer_id", "rank_id", "vessel_id", "ship_owner_id", "opportunity_id", "source", "budget_monthly_usd",
  "join_date", "join_port_id", "planned_leave_date", "planned_leave_port_id", "leave_date", "leave_port_id",
  "status", "notes", "legacy_voyage_id", "legacy_contract_id", "created_by"
)
SELECT
  'CT-' || EXTRACT(YEAR FROM x.join_date)::int || '-'
    || lpad((ROW_NUMBER() OVER (PARTITION BY EXTRACT(YEAR FROM x.join_date) ORDER BY x.join_date, x.contract_id))::text, 4, '0'),
  x.seafarer_id, x.rank_id, x.vessel_id, x.ship_owner_id, x.opportunity_id, 'OPPORTUNITY', x.budget_monthly_usd,
  x.join_date, x.embark_port_id, GREATEST(x.end_date, x.join_date), x.disembark_port_id,
  x.leave_date, CASE WHEN x.leave_date IS NOT NULL THEN x.disembark_port_id END,
  CASE WHEN x.leave_date IS NOT NULL THEN 'LEFT' ELSE 'ONBOARD' END,
  'Chuyển từ ' || x.voyage_code, x.voyage_id, x.contract_id, x.contract_created_by
FROM (
  SELECT ls.*, o.id AS opportunity_id,
    GREATEST(ls.actual_embark_date, ls.start_date) AS join_date,
    CASE WHEN ls.voyage_status = 'ENDED'
      THEN GREATEST(LEAST(ls.actual_disembark_date, ls.end_date), GREATEST(ls.actual_embark_date, ls.start_date)) END AS leave_date
  FROM "legacy_slot" ls JOIN "opportunity" o ON o.legacy_position_id = ls.position_id
  WHERE ls.boarded
) x;

INSERT INTO "seafarer_voyage_log" ("voyage_id", "action", "payload")
SELECT sv.id, 'MIGRATE', jsonb_build_object('legacy_voyage_id', sv.legacy_voyage_id, 'legacy_contract_id', sv.legacy_contract_id)
FROM "seafarer_voyage" sv;

-- Người đã có chuyến: ứng viên được chốt. Người có hợp đồng chưa lên tàu (chuyến chưa bắt đầu, hoặc hợp đồng chưa hiệu lực): ứng viên mang nhãn Chủ tàu đã chọn.
INSERT INTO "opportunity_candidate" ("opportunity_id", "seafarer_id", "status", "owner_selected_at", "owner_selected_by", "added_by")
SELECT o.id, ls.seafarer_id,
  CASE WHEN ls.boarded THEN 'PLACED' ELSE 'PICKED' END,
  CASE WHEN NOT ls.boarded THEN NOW() END,
  CASE WHEN NOT ls.boarded THEN (SELECT u.id FROM "user" u WHERE u.id = ls.contract_created_by) END,
  ls.contract_created_by
FROM "legacy_slot" ls JOIN "opportunity" o ON o.legacy_position_id = ls.position_id
WHERE ls.contract_id IS NOT NULL;

-- Bộ đếm mã: CH 3 chữ số, CT mới 4 chữ số (kind riêng, không đụng bộ đếm VOYAGE cũ).
INSERT INTO "code_counter" ("kind", "year", "last_value")
SELECT 'OPPORTUNITY', split_part(code, '-', 2)::smallint, MAX(split_part(code, '-', 3)::int) FROM "opportunity" GROUP BY 2
ON CONFLICT ("kind", "year") DO UPDATE SET "last_value" = GREATEST("code_counter"."last_value", EXCLUDED."last_value");
INSERT INTO "code_counter" ("kind", "year", "last_value")
SELECT 'VOYAGE1', split_part(code, '-', 2)::smallint, MAX(split_part(code, '-', 3)::int) FROM "seafarer_voyage" GROUP BY 2
ON CONFLICT ("kind", "year") DO UPDATE SET "last_value" = GREATEST("code_counter"."last_value", EXCLUDED."last_value");

-- Trạng thái thuyền viên từ nay theo chuyến mới.
DO $$
DECLARE n_on INTEGER; n_off INTEGER;
BEGIN
  UPDATE "seafarer" s SET "status" = 'ON_VESSEL'
  WHERE s.deleted_at IS NULL AND s.status <> 'ON_VESSEL' AND s.status <> 'INACTIVE'
    AND EXISTS (SELECT 1 FROM "seafarer_voyage" sv WHERE sv.seafarer_id = s.id AND sv.status = 'ONBOARD' AND sv.deleted_at IS NULL);
  GET DIAGNOSTICS n_on = ROW_COUNT;
  UPDATE "seafarer" s SET "status" = 'AVAILABLE'
  WHERE s.deleted_at IS NULL AND s.status = 'ON_VESSEL'
    AND NOT EXISTS (SELECT 1 FROM "seafarer_voyage" sv WHERE sv.seafarer_id = s.id AND sv.status = 'ONBOARD' AND sv.deleted_at IS NULL);
  GET DIAGNOSTICS n_off = ROW_COUNT;
  RAISE NOTICE 'seafarer.status: % người sang ON_VESSEL, % người sang AVAILABLE', n_on, n_off;
END $$;

-- ---------- Quyền ----------
-- Vai trò đang được tạo chuyến thì có đủ quyền cơ hội; phạm vi cơ hội theo phạm vi chuyến.
INSERT INTO "role_permission" ("role_id", "permission")
SELECT rp.role_id, p.permission
FROM "role_permission" rp
CROSS JOIN (VALUES ('opportunity.view'), ('opportunity.create'), ('opportunity.update'), ('opportunity.send'), ('opportunity.close')) AS p(permission)
WHERE rp.permission = 'voyage.create'
ON CONFLICT DO NOTHING;
UPDATE "role" SET "scopes" = "scopes" || jsonb_build_object('opportunity', "scopes" -> 'voyage')
WHERE "scopes" ? 'voyage';
